using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using Gunt.ControlCenter.Models;using Gunt.ControlCenter.Services;
namespace Gunt.ControlCenter.Views {
 public sealed partial class MainWindow {
  ListBox sessionResults;
  DevelopmentSession SelectedSession(){return Dispatcher.Invoke(new Func<DevelopmentSession>(()=>{if(sessionDraft==null)throw new ArgumentException("세션을 선택하세요.");if(SessionDraftDirty&&!SaveSessionDraft())throw new InvalidOperationException("세션 저장에 실패했습니다.");return CloneSession(sessionDraft);}));}
  string LaunchSessionFromUi(bool resume){ProjectEntry p;DevelopmentSession s;DeveloperPreferences prefs=null;if(resume){var last=vm.Service.ResumeConfiguration();p=last.Item1;s=last.Item2;prefs=last.Item3;}else{p=vm.Service.ActiveProject();s=SelectedSession();}string summary=vm.Service.SessionPreview(p,s,prefs);bool yes=Dispatcher.Invoke(new Func<bool>(()=>Decide("개발 세션 실행",summary,"이 구성으로 시작","취소")==0));if(!yes)return "개발 세션 시작을 취소했습니다.";bool custom=s.Actions.Any(a=>a.Enabled&&a.Kind=="command");bool consent=!custom||Dispatcher.Invoke(new Func<bool>(()=>Decide("프로젝트 명령 실행 동의",p.Name+"\n"+String.Join("\n",p.Commands??new List<string>()),"이 명령 실행 허용","명령 제외")==0));var result=vm.Service.StartSession(p,s,custom&&consent,false,prefs);string report=String.Join("\n",result.Actions.Select(x=>x.ToString()));Dispatcher.Invoke((Action)(()=>{if(sessionResults!=null){sessionResults.ItemsSource=result.Actions;sessionResults.Visibility=Visibility.Visible;}if(sessionDetails!=null)sessionDetails.Text=result.Result+" · 실행 요청 결과 (프로그램 준비 완료 여부는 별도 확인)";}));return result.Result+" · "+result.Actions.Count+"개 단계 결과를 확인하세요.";}
  void BuildSmartAutomation(){Text("사용 중인 규칙만 조건이 맞을 때 실행됩니다. 세션 종료 조건은 수동 종료 기록 기준입니다.",true);ruleList=DataList("스마트 자동화 규칙",170);var rules=vm.Service.Automation().Rules;ruleList.ItemsSource=rules;ruleList.Height=Math.Min(264,rules.Count*60);content.Children.Add(ruleList);if(rules.Count==0)Text("등록된 규칙이 없습니다. 규칙 추가로 시작하세요.",true);var details=new TextBlock{Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,4,0,12)};content.Children.Add(details);ruleList.SelectionChanged+=delegate{var selected=ruleList.SelectedItem as AutomationRule;if(selected!=null)details.Text=(selected.Enabled?"사용 중":"중지됨 · 실행하지 않음")+"\n조건: "+DeveloperText.Trigger(selected.Trigger)+" · "+selected.TriggerValue+"\n추가 조건: "+(selected.Power=="any"?"전원 제한 없음":selected.Power)+"\n동작: "+DeveloperText.Action(selected.Action)+" · "+selected.Value+"\n우선순위 "+selected.Priority+" · 재실행 대기 "+selected.CooldownSeconds+"초\n최근 실행: "+DesktopService.S(vm.Service.State("automation-times"),selected.Id,"없음");};if(ruleList.Items.Count>0)ruleList.SelectedIndex=0;var a=Actions();Action(a,"규칙 추가",()=>{Dispatcher.Invoke((Action)(()=>EditAutomationRule(new AutomationRule{Name="새 규칙"})));return "자동화 규칙 편집을 마쳤습니다.";});Action(a,"규칙 편집",()=>{var rule=SelectedRule();var copy=vm.Service.Json.Deserialize<AutomationRule>(vm.Service.Json.Serialize(rule));Dispatcher.Invoke((Action)(()=>EditAutomationRule(copy)));return "규칙 편집을 마쳤습니다.";});Action(a,"사용 / 중지",()=>{var rule=SelectedRule();if(!rule.Enabled&&!Dispatcher.Invoke(new Func<bool>(()=>Decide("자동화 사용",rule.Name+"\n조건: "+DeveloperText.Trigger(rule.Trigger)+"\n동작: "+DeveloperText.Action(rule.Action)+"\n조건이 맞으면 사용자 조작 없이 실행됩니다.","이 규칙 사용","취소")==0)))return "규칙 사용을 취소했습니다.";rule.Enabled=!rule.Enabled;vm.Service.SaveRule(rule);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));return rule.Enabled?"규칙 사용을 켰습니다.":"규칙을 중지했습니다.";});Action(a,"규칙 삭제",()=>{var rule=SelectedRule();if(Dispatcher.Invoke(new Func<bool>(()=>Decide("규칙 삭제",rule.Name+"을 삭제할까요?","삭제","취소")==0))){vm.Service.DeleteRule(rule.Id);Dispatcher.Invoke((Action)(()=>Show("smart-automation")));}return "규칙 삭제 처리를 마쳤습니다.";});var events=new TextBox{Text=vm.Service.AutomationHistory(),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=180,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};content.Children.Add(new Expander{Header="자동화 실행 이력",Content=events});Action(a,"실행 이력 갱신",()=>{string text=vm.Service.AutomationHistory();Dispatcher.Invoke((Action)(()=>events.Text=text));return "규칙 이력을 갱신했습니다.";});}
  AutomationRule SelectedRule(){return Dispatcher.Invoke(new Func<AutomationRule>(()=>{var rule=ruleList.SelectedItem as AutomationRule;if(rule==null)throw new ArgumentException("규칙을 선택하세요.");return rule;}));}
  void EditAutomationRule(AutomationRule rule){StackPanel panel;var w=EditorWindow("스마트 자동화 규칙 편집",out panel);var name=EditBox(panel,"규칙 이름",rule.Name);SectionHeader(panel,"언제 · 실행 조건");var trigger=Choice(panel,"조건",new[]{"session-started","session-ended","application-running","ac-connected","battery","monitor-changed"}.Select(x=>new ChoiceOption(x,DeveloperText.Trigger(x))),rule.Trigger);var triggerValue=EditBox(panel,"조건 값 (앱 이름 또는 프로젝트 ID, 세션은 비우면 모두)",rule.TriggerValue);SectionHeader(panel,"실행할 동작");var action=Choice(panel,"실행 동작",new[]{"profile","restore-owned","monitor-show","monitor-hide","wallpaper-pause","wallpaper-play","open-project","session"}.Select(x=>new ChoiceOption(x,DeveloperText.Action(x))),rule.Action);var value=EditBox(panel,"동작 대상 ID (프로필·프로젝트·세션)",rule.Value);panel.Children.Add(new TextBlock{Text="프로필: "+String.Join(", ",vm.Service.Profiles().Select(x=>x.Id))+"\n프로젝트: "+String.Join(", ",vm.Service.Projects().Select(x=>x.Id))+"\n세션: "+String.Join(", ",vm.Service.Sessions().Presets.Select(x=>x.Id)),Foreground=Muted,TextWrapping=TextWrapping.Wrap});SectionHeader(panel,"추가 조건");var power=Choice(panel,"추가 전원 조건",new[]{new ChoiceOption("any","제한 없음"),new ChoiceOption("ac","AC 연결"),new ChoiceOption("battery","배터리")},rule.Power);var exceptions=EditBox(panel,"제외할 실행 앱 이름 (쉼표 구분)",String.Join(",",rule.Exceptions));SectionHeader(panel,"고급 · 우선순위 및 재실행");var priority=EditBox(panel,"우선순위 0–100",rule.Priority.ToString());var cooldown=EditBox(panel,"재실행 대기 10–86400초",rule.CooldownSeconds.ToString());panel.Children.Add(new TextBlock{Text="저장만으로 새 규칙을 켜지 않습니다. 목록의 사용/중지에서 명시적으로 켜세요.",Foreground=Muted,TextWrapping=TextWrapping.Wrap});SaveEditor(w,panel,()=>{rule.Name=name.Text.Trim();rule.Trigger=Convert.ToString(trigger.SelectedValue);rule.TriggerValue=triggerValue.Text.Trim();rule.Action=Convert.ToString(action.SelectedValue);rule.Value=value.Text.Trim();rule.Power=Convert.ToString(power.SelectedValue);rule.Exceptions=exceptions.Text.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToList();rule.Priority=Int32.Parse(priority.Text);rule.CooldownSeconds=Int32.Parse(cooldown.Text);vm.Service.SaveRule(rule);});w.ShowDialog();Show("smart-automation");}
 }
}
